from __future__ import annotations

import hashlib
import json
from enum import StrEnum
from typing import ClassVar, Literal

from pydantic import BaseModel, ConfigDict, Field, model_validator

from .jobs import IngestionJobStore, ResourceFormat, ResourceProfile


def _to_camel(value: str) -> str:
    head, *tail = value.split("_")
    return head + "".join(part.title() for part in tail)


class _WireModel(BaseModel):
    model_config = ConfigDict(
        alias_generator=_to_camel,
        populate_by_name=True,
        extra="forbid",
        str_strip_whitespace=True,
    )


class MappingLayout(StrEnum):
    WIDE_TABLE = "WIDE_TABLE"
    LONG_TABLE = "LONG_TABLE"
    NAMED_ARRAYS = "NAMED_ARRAYS"


class MappingValidationError(ValueError):
    pass


class ChannelSpec(_WireModel):
    selector: str = Field(min_length=1, max_length=500)
    name: str = Field(min_length=1, max_length=200)
    unit: str | None = Field(default=None, max_length=100)


class MappingSpec(_WireModel):
    schema_version: Literal["1.0"] = "1.0"
    job_revision: int = Field(ge=1)
    resource_id: str = Field(pattern=r"^res_[a-f0-9]{24}$")
    resource_sha256: str = Field(pattern=r"^[a-f0-9]{64}$")
    layout: MappingLayout
    record_selector: str | None = Field(default=None, max_length=500)
    time_selector: str = Field(min_length=1, max_length=500)
    channel_selector: str | None = Field(default=None, max_length=500)
    value_selector: str | None = Field(default=None, max_length=500)
    signal_selector: str | None = Field(default=None, max_length=500)
    sample_axis: int | None = Field(default=None, ge=0, le=8)
    channel_axis: int | None = Field(default=None, ge=0, le=8)
    channels: list[ChannelSpec] = Field(min_length=1, max_length=10_000)
    annotations: list[str] = Field(default_factory=list, max_length=100)

    @model_validator(mode="after")
    def layout_fields_match(self) -> MappingSpec:
        if len({channel.selector for channel in self.channels}) != len(self.channels):
            raise ValueError("channel selectors must be unique")
        if len({channel.name for channel in self.channels}) != len(self.channels):
            raise ValueError("channel names must be unique")
        if self.layout is MappingLayout.LONG_TABLE:
            if not self.channel_selector or not self.value_selector or self.signal_selector:
                raise ValueError("long mappings require channel and value selectors")
        elif self.layout is MappingLayout.NAMED_ARRAYS:
            if (
                not self.signal_selector
                or self.sample_axis is None
                or self.channel_axis is None
                or self.sample_axis == self.channel_axis
            ):
                raise ValueError("array mappings require distinct sample and channel axes")
        elif self.channel_selector or self.value_selector or self.signal_selector:
            raise ValueError("wide mappings use channel selectors directly")
        return self

    def require_confirmation_fields(self) -> None:
        if any(not channel.unit for channel in self.channels):
            raise MappingValidationError("Every mapped channel requires an explicit unit")


class MappingProposal(_WireModel):
    resource_id: str
    candidates: list[MappingSpec]
    issues: list[str]
    requires_confirmation: bool = True


class ConfirmedMapping(_WireModel):
    mapping_sha256: str = Field(pattern=r"^[a-f0-9]{64}$")
    mapping: MappingSpec
    created: bool


class MappingService:
    TIME_NAMES: ClassVar[tuple[str, ...]] = ("time", "timestamp", "time_seconds", "seconds", "t")
    RECORD_NAMES: ClassVar[tuple[str, ...]] = (
        "record",
        "record_id",
        "run",
        "run_id",
        "sequence",
        "sequence_id",
    )
    CHANNEL_NAMES: ClassVar[tuple[str, ...]] = (
        "channel",
        "channel_id",
        "signal",
        "signal_id",
    )
    VALUE_NAMES: ClassVar[tuple[str, ...]] = ("value", "measurement", "reading")

    def __init__(self, jobs: IngestionJobStore):
        self.jobs = jobs

    def proposals(self, ingestion_id: str) -> list[MappingProposal]:
        job = self.jobs.get(ingestion_id)
        return [self._proposal(job.job_revision, profile) for profile in self.jobs.list_resources(ingestion_id)]

    def confirm(self, ingestion_id: str, mapping: MappingSpec) -> ConfirmedMapping:
        mapping.require_confirmation_fields()
        profile = next(
            (
                item
                for item in self.jobs.list_resources(ingestion_id)
                if item.resource_id == mapping.resource_id
                and item.content_sha256 == mapping.resource_sha256
            ),
            None,
        )
        if profile is not None:
            self._validate_against_profile(mapping, profile)
        payload = mapping.model_dump(mode="json", by_alias=True)
        canonical = json.dumps(payload, sort_keys=True, separators=(",", ":"))
        digest = hashlib.sha256(canonical.encode()).hexdigest()
        persisted, created = self.jobs.confirm_mapping(
            ingestion_id=ingestion_id,
            expected_job_revision=mapping.job_revision,
            resource_id=mapping.resource_id,
            resource_sha256=mapping.resource_sha256,
            mapping_sha256=digest,
            mapping_payload=payload,
        )
        return ConfirmedMapping(
            mapping_sha256=digest,
            mapping=MappingSpec.model_validate(persisted),
            created=created,
        )

    @staticmethod
    def _validate_against_profile(mapping: MappingSpec, profile: ResourceProfile) -> None:
        if mapping.layout in {MappingLayout.WIDE_TABLE, MappingLayout.LONG_TABLE}:
            columns = {column["name"] for column in profile.details.get("columns", [])}
            required = {mapping.time_selector, *(mapping.annotations)}
            if mapping.record_selector:
                required.add(mapping.record_selector)
            if mapping.layout is MappingLayout.WIDE_TABLE:
                required.update(channel.selector for channel in mapping.channels)
            else:
                required.update({mapping.channel_selector, mapping.value_selector})
                if any(channel.selector == "*" for channel in mapping.channels):
                    raise MappingValidationError(
                        "Long-table channel values must be selected explicitly"
                    )
            if None in required or not required.issubset(columns):
                raise MappingValidationError("Mapping selector is absent from the tabular schema")
            return
        arrays = {
            array["name"]: array for array in profile.details.get("arrays", [])
        }
        required_arrays = {mapping.time_selector, mapping.signal_selector, *mapping.annotations}
        if None in required_arrays or not required_arrays.issubset(arrays):
            raise MappingValidationError("Mapping selector is absent from the array schema")
        signal_shape = arrays[mapping.signal_selector]["shape"]
        if max(mapping.sample_axis, mapping.channel_axis) >= len(signal_shape):
            raise MappingValidationError("Mapped array axis is outside the signal shape")
        if signal_shape[mapping.channel_axis] != len(mapping.channels):
            raise MappingValidationError("Mapped channel count differs from the signal array")
        time_shape = arrays[mapping.time_selector]["shape"]
        if len(time_shape) != 1 or time_shape[0] != signal_shape[mapping.sample_axis]:
            raise MappingValidationError("Mapped time array does not match the sample axis")

    def get(self, ingestion_id: str) -> ConfirmedMapping | None:
        payload = self.jobs.get_mapping_payload(ingestion_id)
        if payload is None:
            return None
        canonical = json.dumps(payload, sort_keys=True, separators=(",", ":"))
        return ConfirmedMapping(
            mapping_sha256=hashlib.sha256(canonical.encode()).hexdigest(),
            mapping=MappingSpec.model_validate(payload),
            created=False,
        )

    def _proposal(self, job_revision: int, profile: ResourceProfile) -> MappingProposal:
        if profile.format is ResourceFormat.UNSUPPORTED:
            return MappingProposal(
                resource_id=profile.resource_id,
                candidates=[],
                issues=[profile.details.get("reason", "UNSUPPORTED_FORMAT")],
            )
        if profile.format in {ResourceFormat.CSV, ResourceFormat.TSV, ResourceFormat.PARQUET}:
            return self._table_proposal(job_revision, profile)
        return self._array_proposal(job_revision, profile)

    def _table_proposal(self, job_revision: int, profile: ResourceProfile) -> MappingProposal:
        columns = profile.details.get("columns", [])
        names = [column["name"] for column in columns]
        lower = {name.casefold(): name for name in names}
        time_matches = [lower[name] for name in self.TIME_NAMES if name in lower]
        record_matches = [lower[name] for name in self.RECORD_NAMES if name in lower]
        channel_matches = [lower[name] for name in self.CHANNEL_NAMES if name in lower]
        value_matches = [lower[name] for name in self.VALUE_NAMES if name in lower]
        issues: list[str] = []
        if len(time_matches) != 1:
            issues.append("TIME_SELECTOR_AMBIGUOUS")
            return MappingProposal(resource_id=profile.resource_id, candidates=[], issues=issues)
        if len(record_matches) > 1:
            issues.append("RECORD_SELECTOR_AMBIGUOUS")
            return MappingProposal(resource_id=profile.resource_id, candidates=[], issues=issues)
        if len(channel_matches) > 1 or len(value_matches) > 1:
            issues.append("LONG_LAYOUT_AMBIGUOUS")
            return MappingProposal(resource_id=profile.resource_id, candidates=[], issues=issues)
        time = time_matches[0]
        record = record_matches[0] if record_matches else None
        channel = channel_matches[0] if channel_matches else None
        value = value_matches[0] if value_matches else None
        if channel and value:
            candidates = [
                MappingSpec(
                    job_revision=job_revision,
                    resource_id=profile.resource_id,
                    resource_sha256=profile.content_sha256,
                    layout=MappingLayout.LONG_TABLE,
                    record_selector=record,
                    time_selector=time,
                    channel_selector=channel,
                    value_selector=value,
                    channels=[ChannelSpec(selector="*", name="selected_channel", unit=None)],
                )
            ]
        else:
            numeric = {
                column["name"]
                for column in columns
                if column.get("dtype") not in {"string", "unknown", "bool"}
            }
            selected = [name for name in names if name in numeric and name not in {time, record}]
            candidates = (
                [
                    MappingSpec(
                        job_revision=job_revision,
                        resource_id=profile.resource_id,
                        resource_sha256=profile.content_sha256,
                        layout=MappingLayout.WIDE_TABLE,
                        record_selector=record,
                        time_selector=time,
                        channels=[ChannelSpec(selector=name, name=name, unit=None) for name in selected],
from __future__ import annotations

from datetime import UTC, datetime
from pathlib import Path
from typing import Protocol

from .acquisition import AcquiredAsset, AcquisitionError
from .archive import ArchiveError, SafeArchiveExtractor
from .contracts import ApprovedManifest, ManifestAsset
from .inventory import InventoryError, ResourceInventory
from .jobs import (
    AssetReceipt,
    IngestionJob,
    IngestionJobConflict,
    IngestionJobStore,
    IngestionState,
    ResourceFormat,
)
from .service import (
    ApprovedSourceResolutionError,
    ApprovedSourceResolver,
    ResolvedApprovedSource,
)


class AssetAcquirer(Protocol):
    def acquire(self, manifest: ApprovedManifest, asset: ManifestAsset) -> AcquiredAsset: ...

    def has_verified_content(self, content_sha256: str, size_bytes: int) -> bool: ...

    def verified_content_path(self, content_sha256: str) -> Path: ...


class AcquisitionWorker:
    def __init__(
        self,
        jobs: IngestionJobStore,
        resolver: ApprovedSourceResolver,
        acquirer: AssetAcquirer,
        extractor: SafeArchiveExtractor | None = None,
        inventory: ResourceInventory | None = None,
    ):
        self.jobs = jobs
        self.resolver = resolver
        self.acquirer = acquirer
        self.extractor = extractor
        self.inventory = inventory

    def recover_interrupted(self) -> int:
        return self.jobs.requeue_interrupted_acquisitions()

    def run_once(self) -> IngestionJob | None:
        job = self.jobs.claim_next_acquisition()
        if job is None:
            return None
        try:
            resolved = self.resolver.resolve(job.approved_source_id)
            self._verify_job_manifest(job, resolved)
            assets = {asset.asset_id: asset for asset in resolved.manifest.data_assets}
            if set(job.asset_ids) - assets.keys():
                raise AcquisitionError("Approved asset selection no longer matches the manifest")
            receipts = {
                receipt.asset_id: receipt for receipt in self.jobs.list_receipts(job.ingestion_id)
            }
            for asset_id in job.asset_ids:
                asset = assets[asset_id]
                existing = receipts.get(asset_id)
                if existing is not None:
                    self._verify_receipt_claims(existing, asset)
                    if self.acquirer.has_verified_content(
                        existing.content_sha256, existing.observed_size_bytes
                    ):
                        continue
                acquired = self.acquirer.acquire(resolved.manifest, asset)
                if acquired.asset_id != asset.asset_id or acquired.size_bytes != asset.size_bytes:
                    raise AcquisitionError("Acquirer returned content for another approved asset")
                self.jobs.record_receipt(self._receipt(job, asset, acquired))
            resource_paths: list[tuple[str, str, Path]] = []
            if self.extractor is not None:
                receipts = {
                    receipt.asset_id: receipt
                    for receipt in self.jobs.list_receipts(job.ingestion_id)
                }
                for asset_id in job.asset_ids:
                    asset = assets[asset_id]
                    if self._is_archive(asset.name):
                        receipt = receipts[asset_id]
                        extraction = self.extractor.extract(
                            self.acquirer.verified_content_path(receipt.content_sha256),
                            receipt.content_sha256,
                        )
                        root = (
                            self.extractor.extracted_dir
                            / receipt.content_sha256[:2]
                            / receipt.content_sha256
                        )
                        resource_paths.extend(
                            (asset_id, file.relative_path, root / file.relative_path)
                            for file in extraction.files
                        )
                    else:
                        receipt = receipts[asset_id]
                        resource_paths.append(
                            (
                                asset_id,
                                asset.name,
                                self.acquirer.verified_content_path(receipt.content_sha256),
                            )
                        )
            if self.inventory is not None:
                self.jobs.set_state(
                    job.ingestion_id,
                    IngestionState.INSPECTING,
                    "Inspecting verified dataset resources",
                )
                profiles = [
                    self.jobs.record_resource(
                        self.inventory.inspect(
                            ingestion_id=job.ingestion_id,
                            asset_id=asset_id,
                            logical_path=logical_path,
                            path=path,
                        )
                    )
                    for asset_id, logical_path, path in resource_paths
                ]
                supported = [
                    profile for profile in profiles if profile.format is not ResourceFormat.UNSUPPORTED
                ]
                if not supported:
                    return self.jobs.set_state(
                        job.ingestion_id,
                        IngestionState.UNSUPPORTED_FORMAT,
                        "No supported time-series resources were found",
                    )
                return self.jobs.set_state(
                    job.ingestion_id,
                    IngestionState.MAPPING,
                    f"Inventoried {len(profiles)} resource(s); mapping is required",
                )
            return self.jobs.set_state(
                job.ingestion_id,
                IngestionState.INSPECTING,
                f"Verified {len(job.asset_ids)} approved asset(s); queued for inventory",
            )
        except (
            AcquisitionError,
            ApprovedSourceResolutionError,
            ArchiveError,
            InventoryError,
            IngestionJobConflict,
        ):
            return self.jobs.set_state(
                job.ingestion_id,
                IngestionState.FAILED,
                "Acquisition failed because an approved asset could not be verified",
            )
        except Exception:
            self.jobs.set_state(
                job.ingestion_id,
                IngestionState.FAILED,
                "Acquisition failed because the worker encountered an internal error",
            )
            raise

    @staticmethod
    def _is_archive(name: str) -> bool:
        lower = name.casefold()
        return lower.endswith((".zip", ".tar", ".tar.gz", ".tar.zst"))

    @staticmethod
    def _verify_job_manifest(job: IngestionJob, resolved: ResolvedApprovedSource) -> None:
        if resolved.approved_source_id != job.approved_source_id:
            raise AcquisitionError("Approved source identity changed after job creation")
        if resolved.manifest_sha256 != job.manifest_sha256:
            raise AcquisitionError("Approved manifest changed after the job was created")

    @staticmethod
    def _verify_receipt_claims(receipt: AssetReceipt, asset: ManifestAsset) -> None:
        checksum = asset.source_checksum
        if (
            receipt.provider_locator != asset.provider_locator
            or receipt.expected_size_bytes != asset.size_bytes
            or receipt.source_checksum_algorithm
            != (checksum.algorithm.value if checksum else None)
            or receipt.source_checksum_value != (checksum.value if checksum else None)
        ):
            raise AcquisitionError("Persisted receipt does not match the approved asset")

    @staticmethod
    def _receipt(
        job: IngestionJob,
        asset: ManifestAsset,
        acquired: AcquiredAsset,
    ) -> AssetReceipt:
        checksum = asset.source_checksum
        return AssetReceipt(
            ingestion_id=job.ingestion_id,
            asset_id=asset.asset_id,
            provider_locator=asset.provider_locator,
            expected_size_bytes=asset.size_bytes,
            source_checksum_algorithm=checksum.algorithm.value if checksum else None,
            source_checksum_value=checksum.value if checksum else None,
            observed_size_bytes=acquired.size_bytes,
            content_sha256=acquired.content_sha256,
            content_key=(
                f"sha256/{acquired.content_sha256[:2]}/{acquired.content_sha256}"
            ),
            acquired_at=datetime.now(UTC),
        )
from __future__ import annotations

import csv
from dataclasses import dataclass
from pathlib import Path

import numpy as np
import pyarrow.parquet as pq

from ..jobs import ResourceFormat


class FormatAdapterError(RuntimeError):
    pass


@dataclass(frozen=True)
class ColumnProfile:
    name: str
    dtype: str
    nullable: bool


@dataclass(frozen=True)
class TableProfile:
    format: ResourceFormat
    row_count: int
    columns: tuple[ColumnProfile, ...]
    row_groups: int | None = None


@dataclass(frozen=True)
class TableData:
    columns: dict[str, np.ndarray]
    source_rows: np.ndarray


class TabularAdapter:
    def __init__(
        self,
        *,
        max_rows: int = 2_000_000,
        max_columns: int = 10_000,
        max_cell_bytes: int = 1_000_000,
    ):
        self.max_rows = max_rows
        self.max_columns = max_columns
        self.max_cell_bytes = max_cell_bytes

    def inspect(self, path: Path, format_: ResourceFormat) -> TableProfile:
        if format_ in {ResourceFormat.CSV, ResourceFormat.TSV}:
            return self._inspect_delimited(path, format_)
        if format_ is ResourceFormat.PARQUET:
            parquet = pq.ParquetFile(path)
            metadata = parquet.metadata
            if metadata.num_rows > self.max_rows or metadata.num_columns > self.max_columns:
                raise FormatAdapterError("Parquet resource exceeds configured shape limits")
            columns = tuple(
                ColumnProfile(field.name, str(field.type), field.nullable)
                for field in parquet.schema_arrow
            )
            return TableProfile(format_, metadata.num_rows, columns, metadata.num_row_groups)
        raise FormatAdapterError("Tabular adapter received another format")

    def read_columns(
        self,
        path: Path,
        format_: ResourceFormat,
        columns: list[str],
    ) -> TableData:
        if not columns or len(columns) != len(set(columns)):
            raise FormatAdapterError("Projected columns must be unique and non-empty")
        profile = self.inspect(path, format_)
        available = {column.name for column in profile.columns}
        if any(column not in available for column in columns):
            raise FormatAdapterError("Projected column is absent from the resource")
        if format_ in {ResourceFormat.CSV, ResourceFormat.TSV}:
            return self._read_delimited(path, format_, columns)
        table = pq.ParquetFile(path).read(columns=columns, use_threads=False)
        values = {
            name: np.asarray(table[name].to_pylist(), dtype=object)
            for name in columns
        }
        return TableData(values, np.arange(1, table.num_rows + 1, dtype=np.int64))

    def _inspect_delimited(self, path: Path, format_: ResourceFormat) -> TableProfile:
        delimiter = "," if format_ is ResourceFormat.CSV else "\t"
        with path.open("r", encoding="utf-8-sig", newline="") as source:
            reader = csv.reader(source, delimiter=delimiter, strict=True)
            try:
                header = next(reader)
            except (StopIteration, csv.Error) as exc:
                raise FormatAdapterError("Delimited resource has no valid header") from exc
            self._validate_header(header)
            samples: list[list[str]] = []
            count = 0
            try:
                for row in reader:
                    count += 1
                    if count > self.max_rows:
                        raise FormatAdapterError("Delimited resource exceeds the row limit")
                    self._validate_row(row, len(header))
                    if len(samples) < 1_000:
                        samples.append(row)
            except csv.Error as exc:
                raise FormatAdapterError("Delimited resource contains malformed quoting") from exc
        columns = tuple(
            ColumnProfile(
                name,
                self._infer_dtype([row[index] for row in samples]),
                any(row[index] == "" for row in samples),
            )
            for index, name in enumerate(header)
        )
        return TableProfile(format_, count, columns)

    def _read_delimited(
        self,
        path: Path,
        format_: ResourceFormat,
        columns: list[str],
    ) -> TableData:
        delimiter = "," if format_ is ResourceFormat.CSV else "\t"
        projected: dict[str, list[object]] = {column: [] for column in columns}
        source_rows: list[int] = []
        with path.open("r", encoding="utf-8-sig", newline="") as source:
            reader = csv.reader(source, delimiter=delimiter, strict=True)
            header = next(reader)
            indices = {column: header.index(column) for column in columns}
            try:
                for source_row, row in enumerate(reader, start=2):
                    if len(source_rows) >= self.max_rows:
                        raise FormatAdapterError("Delimited resource exceeds the row limit")
                    self._validate_row(row, len(header))
                    for column, index in indices.items():
                        projected[column].append(self._parse_scalar(row[index]))
                    source_rows.append(source_row)
            except csv.Error as exc:
                raise FormatAdapterError("Delimited resource contains malformed quoting") from exc
        return TableData(
            {name: np.asarray(values, dtype=object) for name, values in projected.items()},
            np.asarray(source_rows, dtype=np.int64),
        )

    def _validate_header(self, header: list[str]) -> None:
        if not header or len(header) > self.max_columns:
            raise FormatAdapterError("Delimited header exceeds configured column limits")
        if any(not name.strip() or len(name.encode()) > self.max_cell_bytes for name in header):
            raise FormatAdapterError("Delimited header contains an invalid column name")
        if len(header) != len(set(header)):
            raise FormatAdapterError("Delimited header contains duplicate columns")

    def _validate_row(self, row: list[str], width: int) -> None:
        if len(row) != width:
            raise FormatAdapterError("Delimited row width differs from the header")
        if any(len(value.encode()) > self.max_cell_bytes for value in row):
            raise FormatAdapterError("Delimited cell exceeds the configured byte limit")

    @staticmethod
    def _parse_scalar(value: str) -> object:
        if value == "":
            return None
        for parser in (int, float):
            try:
                return parser(value)
            except ValueError:
                pass
        return value

    @classmethod
    def _infer_dtype(cls, values: list[str]) -> str:
        present = [value for value in values if value != ""]
        if not present:
            return "unknown"
        parsed = [cls._parse_scalar(value) for value in present]
        if all(isinstance(value, int) for value in parsed):
            return "int64"
        if all(isinstance(value, (int, float)) for value in parsed):
            return "float64"
        return "string"
from __future__ import annotations

import zipfile
from dataclasses import dataclass
from pathlib import Path

import numpy as np
from scipy.io import loadmat, whosmat

from ..jobs import ResourceFormat
from .tabular import FormatAdapterError


@dataclass(frozen=True)
class ArrayProfile:
    name: str
    shape: tuple[int, ...]
    dtype: str
    size_bytes: int


@dataclass(frozen=True)
class ArrayContainerProfile:
    format: ResourceFormat
    arrays: tuple[ArrayProfile, ...]


@dataclass(frozen=True)
class ArrayData:
    arrays: dict[str, np.ndarray]


class NumericArrayAdapter:
    def __init__(
        self,
        *,
        max_arrays: int = 1_000,
        max_depth: int = 20,
        max_elements_per_array: int = 100_000_000,
        max_total_bytes: int = 2_000_000_000,
        max_npz_expansion_ratio: int = 200,
    ):
        self.max_arrays = max_arrays
        self.max_depth = max_depth
        self.max_elements_per_array = max_elements_per_array
        self.max_total_bytes = max_total_bytes
        self.max_npz_expansion_ratio = max_npz_expansion_ratio

    def inspect(self, path: Path, format_: ResourceFormat) -> ArrayContainerProfile:
        if format_ is ResourceFormat.NPY:
            array = self._safe_npy(path)
            arrays = (self._profile("array", array),)
        elif format_ is ResourceFormat.NPZ:
            self._validate_npz_container(path)
            with np.load(path, allow_pickle=False) as container:
                if len(container.files) > self.max_arrays:
                    raise FormatAdapterError("NPZ contains too many arrays")
                arrays = tuple(
                    self._profile(name, self._safe_npz_array(container, name))
                    for name in sorted(container.files)
                )
        elif format_ is ResourceFormat.MAT:
            arrays = self._inspect_mat(path)
        elif format_ is ResourceFormat.HDF5:
            arrays = self._inspect_hdf5(path)
        else:
            raise FormatAdapterError("Numeric array adapter received another format")
        self._validate_total(arrays)
        if not arrays:
            raise FormatAdapterError("Numeric container has no supported arrays")
        return ArrayContainerProfile(format_, arrays)

    def read_arrays(
        self,
        path: Path,
        format_: ResourceFormat,
        names: list[str],
    ) -> ArrayData:
        if not names or len(names) != len(set(names)):
            raise FormatAdapterError("Selected array names must be unique and non-empty")
        profile = self.inspect(path, format_)
        available = {array.name for array in profile.arrays}
        if any(name not in available for name in names):
            raise FormatAdapterError("Selected array is absent or unsupported")
        if format_ is ResourceFormat.NPY:
            values = {"array": np.asarray(self._safe_npy(path))}
        elif format_ is ResourceFormat.NPZ:
            with np.load(path, allow_pickle=False) as container:
                values = {name: np.asarray(self._safe_npz_array(container, name)) for name in names}
        elif format_ is ResourceFormat.MAT:
            payload = loadmat(path, variable_names=names, squeeze_me=False, struct_as_record=True)
            values = {name: self._validated_array(name, payload[name]) for name in names}
        else:
            values = self._read_hdf5(path, names)
        return ArrayData(values)

    def _safe_npy(self, path: Path) -> np.ndarray:
        try:
            array = np.load(path, mmap_mode="r", allow_pickle=False)
        except (OSError, ValueError) as exc:
            raise FormatAdapterError("NPY header or payload is unsafe") from exc
        return self._validated_array("array", array)

    def _safe_npz_array(self, container, name: str) -> np.ndarray:
        try:
            return self._validated_array(name, container[name])
        except (OSError, ValueError, zipfile.BadZipFile) as exc:
            raise FormatAdapterError("NPZ array payload is unsafe") from exc

    def _validate_npz_container(self, path: Path) -> None:
        try:
            with zipfile.ZipFile(path) as archive:
                members = archive.infolist()
                if len(members) > self.max_arrays:
                    raise FormatAdapterError("NPZ contains too many members")
                total = 0
                compressed = 0
                for member in members:
                    if member.is_dir() or not member.filename.endswith(".npy"):
                        raise FormatAdapterError("NPZ contains a non-array member")
                    total += member.file_size
                    compressed += max(member.compress_size, 1)
                if total > self.max_total_bytes or total > compressed * self.max_npz_expansion_ratio:
                    raise FormatAdapterError("NPZ exceeds configured expansion limits")
        except zipfile.BadZipFile as exc:
            raise FormatAdapterError("NPZ container is invalid") from exc

    def _inspect_mat(self, path: Path) -> tuple[ArrayProfile, ...]:
        try:
            entries = whosmat(path)
        except (OSError, ValueError) as exc:
            raise FormatAdapterError("MAT resource could not be inspected") from exc
        if len(entries) > self.max_arrays:
            raise FormatAdapterError("MAT resource contains too many variables")
        supported = []
        for name, shape, matlab_type in entries:
            if matlab_type in {"cell", "struct", "object", "char", "function", "opaque"}:
                continue
            elements = self._elements(shape)
            supported.append(ArrayProfile(name, tuple(shape), matlab_type, elements * 8))
        return tuple(sorted(supported, key=lambda item: item.name))

    def _inspect_hdf5(self, path: Path) -> tuple[ArrayProfile, ...]:
        try:
            import h5py
        except ImportError as exc:
            raise FormatAdapterError("HDF5 support requires the hdf5 package extra") from exc
        arrays: list[ArrayProfile] = []
        visited = 0
        try:
            with h5py.File(path, "r") as container:
                def visitor(name, item):
                    nonlocal visited
                    visited += 1
                    if visited > self.max_arrays * 4 or len(Path(name).parts) > self.max_depth:
                        raise FormatAdapterError("HDF5 traversal exceeds configured limits")
                    if isinstance(item, h5py.Dataset) and np.issubdtype(item.dtype, np.number):
                        arrays.append(
                            ArrayProfile(
                                name,
                                tuple(item.shape),
                                str(item.dtype),
                                self._elements(item.shape) * item.dtype.itemsize,
                            )
                        )

                container.visititems(visitor)
        except OSError as exc:
            raise FormatAdapterError("HDF5 resource could not be inspected") from exc
        if len(arrays) > self.max_arrays:
            raise FormatAdapterError("HDF5 resource contains too many numeric datasets")
        return tuple(sorted(arrays, key=lambda item: item.name))

    def _read_hdf5(self, path: Path, names: list[str]) -> dict[str, np.ndarray]:
        try:
            import h5py
        except ImportError as exc:
            raise FormatAdapterError("HDF5 support requires the hdf5 package extra") from exc
        try:
            with h5py.File(path, "r") as container:
                return {
                    name: self._validated_array(name, np.asarray(container[name])) for name in names
                }
        except (OSError, KeyError) as exc:
            raise FormatAdapterError("HDF5 selected dataset could not be read") from exc

    def _validated_array(self, name: str, array: np.ndarray) -> np.ndarray:
        if not np.issubdtype(array.dtype, np.number) or array.dtype.hasobject:
            raise FormatAdapterError(f"Array {name!r} is not a safe numeric dtype")
        elements = self._elements(array.shape)
        if elements * array.dtype.itemsize > self.max_total_bytes:
            raise FormatAdapterError(f"Array {name!r} exceeds the configured byte limit")
        return array

    def _profile(self, name: str, array: np.ndarray) -> ArrayProfile:
        return ArrayProfile(name, tuple(array.shape), str(array.dtype), int(array.nbytes))

    def _elements(self, shape) -> int:
        elements = 1
        for dimension in shape:
            if dimension < 0:
                raise FormatAdapterError("Array has an invalid shape")
            elements *= int(dimension)
            if elements > self.max_elements_per_array:
                raise FormatAdapterError("Array exceeds the configured element limit")
        return elements

    def _validate_total(self, arrays: tuple[ArrayProfile, ...]) -> None:
        if sum(array.size_bytes for array in arrays) > self.max_total_bytes:
            raise FormatAdapterError("Numeric container exceeds the configured byte limit")

