    def confirm_mapping(
        self,
        *,
        ingestion_id: str,
        expected_job_revision: int,
        resource_id: str,
        resource_sha256: str,
        mapping_sha256: str,
        mapping_payload: dict,
    ) -> tuple[dict, bool]:
        canonical = json.dumps(mapping_payload, sort_keys=True, separators=(",", ":"))
        now = datetime.now(UTC).isoformat()
        with self._lock:
