            try:
                job_row = self.connection.execute(
                    "SELECT * FROM ingestion_jobs WHERE ingestion_id = ?",
                    (ingestion_id,),
                ).fetchone()
                if job_row is None:
                    raise IngestionJobNotFound("Ingestion job not found")
                existing = self.connection.execute(
