    @staticmethod
    def _resource(row: sqlite3.Row) -> ResourceProfile:
        return ResourceProfile(
            resource_id=row["resource_id"],
            ingestion_id=row["ingestion_id"],
            asset_id=row["asset_id"],
            logical_path=row["logical_path"],
            size_bytes=row["size_bytes"],
