                        "Confirmed mapping queued for deterministic import",
                        now,
                        ingestion_id,
                    ),
                )
                self.connection.execute("COMMIT")
                return mapping_payload, True
            except Exception:
                self.connection.execute("ROLLBACK")
                raise

